import json
nb=json.load(open('/tmp/nbout_andes_sim_demo.ipynb'))
cells=nb['cells']
for i,c in enumerate(cells):
    t=c['cell_type']
    src=''.join(c['source'])
    if t=='markdown':
        first=src.strip().splitlines()[0] if src.strip() else '(empty)'
        print(f"[{i}] MD: {first[:90]}")
    else:
        print(f"[{i}] CODE:")
        for ln in src.splitlines()[:6]:
            print("     |", ln)
        outs=c.get('outputs',[])
        for o in outs:
            ot=o.get('output_type')
            if ot=='stream':
                txt=''.join(o.get('text',[]))
                print("     OUT[stream]:", txt[:300].replace('\n','\\n'))
            elif ot=='error':
                print("     OUT[ERROR]:", o.get('ename'), o.get('evalue')[:200])
                for tl in o.get('traceback',[])[-4:]:
                    import re
                    print("       ", re.sub(r'\x1b\[[0-9;]*m','',tl)[:200])
            elif ot in ('execute_result','display_data'):
                d=o.get('data',{})
                if 'text/plain' in d:
                    print("     OUT[result]:", ''.join(d['text/plain'])[:200].replace('\n','\\n'))
                else:
                    print("     OUT[display]:", list(d.keys()))
        print()
